def common_elements(arr1, arr2):
    # Create a hash table to store the elements in arr1
    hash_table = {}
    for element in arr1:
        hash_table[element] = True

    # Traverse arr2 and check if the elements are in the hash table
    for element in arr2:
        if element in hash_table:
            yield element
